import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

const API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [filtreKategori, setFiltreKategori] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null);
  const [aiCevap, setAiCevap] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("API Hatası:", err));
  }, []);

  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);
  const toplamButce = favoriler.reduce((toplam, m) => toplam + (parseInt(m.ucret) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) {
      setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    } else {
      setFavoriler([...favoriler, mekan]);
    }
  };

  const rotayiTemizle = () => {
    if (window.confirm("Rotayı tamamen sıfırlamak istiyor musun?")) {
      setFavoriler([]); 
    }
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Harita için önce listene mekan eklemelisin!");
    const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join("/");
    const haritaUrl = `https://www.google.com/maps/dir/${duraklar}`;
    window.open(haritaUrl, '_blank');
  };

  const askAI = async (mekan) => {
    setLoading(true); 
    setAiCevap("");
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash"});
      const prompt = `${mekan.ad} hakkında turistler için 2 kısa, ilgi çekici cümle kur. Türkçe cevap ver.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) {
      setAiCevap("Hata oluştu: " + error.message);
    } finally { 
      setLoading(false); 
    }
  };

  const filtrelenmisMekanlar = mekanlar.filter(m => {
    const katUygun = filtreKategori === 'Hepsi' || m.kategori === filtreKategori;
    const sureUygun = !maxSure || m.sure <= parseInt(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="app-container">
      <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap" rel="stylesheet" />
      <style>{`
        :root { --primary: #0e7490; --accent: #f97316; --bg: #f0f9ff; }
        body { margin: 0; font-family: 'Poppins', sans-serif; background: var(--bg); }
        .app-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 20px; }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 20px 0; }
        .brand { font-size: 26px; font-weight: 800; color: var(--primary); }
        .nav-stats { display: flex; gap: 20px; background: white; padding: 10px 20px; border-radius: 50px; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }
        .filters-container { background: white; padding: 20px; border-radius: 20px; display: flex; gap: 15px; margin-bottom: 30px; align-items: center; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 25px; }
        .card { background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.05); transition: 0.3s; }
        .card:hover { transform: translateY(-5px); }
        .card-img { width: 100%; height: 200px; object-fit: cover; }
        .card-body { padding: 20px; }
        .price { color: var(--primary); font-weight: 700; background: #ecfeff; padding: 5px 10px; border-radius: 8px; }
        .btn-add { background: var(--primary); color: white; width: 100%; padding: 10px; border: none; border-radius: 10px; cursor: pointer; font-weight: 600; }
        .btn-remove { background: #ef4444; color: white; width: 100%; padding: 10px; border: none; border-radius: 10px; cursor: pointer; }
      `}</style>

      <nav className="navbar">
        <div className="brand">🧭 ROTA<span>ASİSTANI</span></div>
        <div className="nav-stats">
          <div>SÜRE: <strong>{saat}s {dakika}dk</strong></div>
          <div>BÜTÇE: <strong style={{color: 'var(--accent)'}}>{toplamButce} ₺</strong></div>
        </div>
      </nav>

      <div className="filters-container">
        <select onChange={(e) => setFiltreKategori(e.target.value)} style={{padding: '10px', borderRadius: '10px'}}>
          <option value="Hepsi">Hepsi</option>
          <option value="Tarih">Tarih</option>
          <option value="Doğa">Doğa</option>
          <option value="Eğlence">Eğlence</option>
          <option value="Yemek">Yemek</option>
        </select>
        <button onClick={rotayiHaritadaGoster} style={{background: 'var(--primary)', color: 'white', padding: '10px 20px', borderRadius: '10px', border: 'none', cursor: 'pointer'}}>Haritada Gör</button>
        <button onClick={rotayiTemizle} style={{background: 'none', border: '1px solid #ef4444', color: '#ef4444', padding: '10px 20px', borderRadius: '10px', cursor: 'pointer'}}>Sıfırla</button>
      </div>

      <div className="grid">
        {filtrelenmisMekanlar.map((mekan) => {
          const favorideMi = favoriler.some(f => f.id === mekan.id);
          return (
            <div key={mekan.id} className="card">
              <img src={mekan.resim} className="card-img" alt={mekan.ad} />
              <div className="card-body">
                <h3>{mekan.ad}</h3>
                <p style={{fontSize: '13px', color: '#64748b'}}>{mekan.aciklama}</p>
                <div style={{display: 'flex', justifyContent: 'space-between', marginTop: '15px'}}>
                  <span>⏱ {mekan.sure} dk</span>
                  <span className="price">{mekan.ucret === 0 ? "Ücretsiz" : `${mekan.ucret} ₺`}</span>
                </div>
                <div style={{display: 'flex', gap: '10px', marginTop: '20px'}}>
                  <button onClick={() => { setSeciliMekan(mekan); askAI(mekan); }} style={{flex: 1, padding: '10px', borderRadius: '10px', border: '1px solid #ddd', cursor: 'pointer'}}>AI Bilgi</button>
                  <button onClick={() => toggleFavori(mekan)} className={favorideMi ? 'btn-remove' : 'btn-add'}>
                    {favorideMi ? 'Çıkar' : 'Ekle +'}
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {seciliMekan && (
        <div onClick={() => setSeciliMekan(null)} style={{position:'fixed', top:0, left:0, width:'100%', height:'100%', background:'rgba(0,0,0,0.5)', display:'flex', alignItems:'center', justifyContent:'center', zIndex:1000}}>
          <div onClick={e => e.stopPropagation()} style={{background:'white', padding:'30px', borderRadius:'20px', maxWidth:'500px'}}>
            <h2>{seciliMekan.ad}</h2>
            <div style={{background:'#f0f9ff', padding:'15px', borderRadius:'10px', marginTop:'15px'}}>
              {loading ? "Yükleniyor..." : aiCevap}
            </div>
            <button onClick={() => setSeciliMekan(null)} style={{marginTop:'20px', width:'100%', padding:'10px', borderRadius:'10px', border:'none', background: 'var(--primary)', color: 'white', cursor: 'pointer'}}>Kapat</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
